local module = {}
local _prefabs

local function _loadRS()
    local uiPrefabs = game.ReplicatedStorage:FindFirstChild("UIPrefabs")
    if uiPrefabs then
        local prefabs = {}
        for i, v in pairs(uiPrefabs:GetChildren()) do
            prefabs[v.Name] = v
        end
        return prefabs
    end
    return {}
end

function module.LoadPrefab(prefabName, prefab)
    if _prefabs[prefabName] then
        print("[ NezaUI ] Prefab [" .. prefabName .. "] has been recovered")
    end
    _prefabs[prefabName] = prefab
end

function module.GetPrefab(prefabName)
    return _prefabs[prefabName]
end

_prefabs = _loadRS()
return module